// Normaliza e deduplica os leads (telefone no padrão brasileiro)
const items = $input.all();
const seen = new Set();
const result = [];

for (const item of items) {
  const data = item.json;

  let telefone = data.phoneUnformatted || data.phone || '';
  if (!telefone) continue;

  // Tira tudo que não é número
  telefone = String(telefone).replace(/[^0-9]/g, '');

  // Remove +55 se já tiver (adicionamos de novo no final)
  if (telefone.startsWith('55') && telefone.length > 11) {
    telefone = telefone.substring(2);
  }

  // Remove o zero do DDD se houver
  if (telefone.startsWith('0')) {
    telefone = telefone.substring(1);
  }

  // Brasil: celular = 11 dígitos (DDD + 9 + 8) | fixo = 10 dígitos (DDD + 8)
  if (telefone.length === 10) {
    telefone = '55' + telefone; // fixo
  } else if (telefone.length === 11) {
    telefone = '55' + telefone; // celular
  } else {
    continue; // formato inválido
  }

  // Resultado: 55 + DDD + número = 12 ou 13 dígitos
  if (telefone.length < 12 || telefone.length > 13) continue;
  if (seen.has(telefone)) continue;
  seen.add(telefone);

  const nome = data.title || data.name || '';
  const nomeCurto = nome.split(/[-|,]/)[0].trim();

  result.push({
    json: {
      nome_completo: nome,
      nome_curto: nomeCurto,
      telefone: telefone,
      website: data.website || '',
      tem_site: !!(data.website && data.website.length > 5),
      endereco: data.address || '',
      cidade: data.city || '',
      categoria: data.categoryName || '',
      rating: data.totalScore || 0,
      reviews: data.reviewsCount || 0,
      google_url: data.url || ''
    }
  });
}

return result;

// Mantém só os leads que realmente têm WhatsApp ativo
const items = $input.all();
const result = [];
const leadsOriginais = $('Normalizar Dados').all();

for (const item of items) {
  const validacao = item.json;

  if (Array.isArray(validacao)) {
    for (const numero of validacao) {
      const temWhatsapp = numero.exists === true;

      if (temWhatsapp) {
        const telefoneValidado = String(numero.number || '').replace(/[^0-9]/g, '');

        const leadOriginal = leadsOriginais.find(
          l => String(l.json.telefone).replace(/[^0-9]/g, '') === telefoneValidado
        );

        if (leadOriginal) {
          result.push({
            json: {
              ...leadOriginal.json,
              whatsapp_validado: true,
              jid: numero.jid
            }
          });
        }
      }
    }
  }
}

return result;

// Registro dos envios realizados
return [{
  json: {
    data: new Date().toISOString(),
    nome: $json.nome_completo || $json.nome_curto,
    telefone: $json.telefone,
    cidade: $json.cidade,
    categoria: $json.categoria,
    rating: $json.rating,
    google_url: $json.google_url,
    status: 'mensagem_enviada'
  }
}];

// Registro dos leads que já têm site (oportunidade de redesign)
